int rc = fork();
if (rc < 0) {
    exit(1);                       // 실패
} else if (rc == 0) {              // 자식
    char *args[] = {"wc", "p3.c", NULL};
    execvp(args[0], args);         // 성공하면 돌아오지 않는다
} else {                           // 부모: rc == 자식 PID
    int done = wait(NULL);         // 자식이 끝날 때까지 대기
    printf("child %d finished\n", done);
}

#include <stdlib.h>
#include <unistd.h>
int main(void) {
    if (fork() == 0)
        exit(0);       // 자식 종료 → 좀비
    sleep(30);         // 이 30초 동안 자식은 좀비로 남는다
    return 0;          // 부모가 끝나면 init이 좀비를 회수
}

int fd[2];
pipe(fd);                         // fd[0] 읽기, fd[1] 쓰기
if (fork() == 0) {                // 자식
    close(fd[1]);
    char buf[32] = {0};
    read(fd[0], buf, sizeof buf - 1);
    printf("child got: %s\n", buf);
    return 0;
}
close(fd[0]);                     // 부모
write(fd[1], "hello", 5);
close(fd[1]);
wait(NULL);
